        int[] frequency = new int[nums.length + 1];
        frequency[0] = 1;

        int oddCount = 0;
        int answer = 0;

        for (int value : nums) {
            oddCount += value % 2;

            if (oddCount >= k) {
                answer += frequency[oddCount - k];
            }

            frequency[oddCount]++;
        }

        return answer;
    }
}
